 "content": "def transform(grid):
    """Reduce a grid by treating each 3x3 patch as one cell.

    The sparse foreground marks (colors other than 0 and 5) survive; 0 and 5
    are background/noise in the source texture.
    """
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            marks = {grid[i][j] for i in range(r, min(r + 3, len(grid)))
                     for j in range(c, min(c + 3, len(grid[0])))
                     if grid[i][j] not in (0, 5)}
            row.append(next(iter(marks)) if marks else 0)
        out.append(row)
    return out
